<div class="card"><div class="card-header">Estoque e Ficha Técnica</div><div class="table-responsive"><table class="table"><thead><tr><th>Insumo</th><th>Unidade</th><th>Atual</th><th>Mínimo</th><th>Status</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= htmlspecialchars($i['name']) ?></td><td><?= htmlspecialchars($i['unit']) ?></td><td><?= htmlspecialchars((string)$i['current_stock']) ?></td><td><?= htmlspecialchars((string)$i['min_stock']) ?></td><td><span class="badge <?= $i['current_stock']<=$i['min_stock']?'text-bg-danger':'text-bg-success' ?>"><?= $i['current_stock']<=$i['min_stock']?'Baixo':'OK' ?></span></td></tr><?php endforeach; ?></tbody></table></div></div>
